def execute_command(image) -> str:
    image_patch = ImagePatch(image)
    red_shirt_player_patches = image_patch.find("red shirt player")
    striped_shirt_guy_patches = image_patch.find("striped shirt guy")

    if not red_shirt_player_patches or not striped_shirt_guy_patches:
        return "No red shirt player or striped shirt guy found."

    closest_distance = float('inf')
    result = None

    for red_shirt_player in red_shirt_player_patches:
        for striped_shirt_guy in striped_shirt_guy_patches:
            dist = distance(red_shirt_player, striped_shirt_guy)
            if 0 < dist < closest_distance:
                closest_distance = dist
                result = red_shirt_player

    if result:
        return f"The red shirt player is {closest_distance:.2f} units away from the striped shirt guy."
    else:
        return "Red shirt player and striped shirt guy are overlapping."

