    center_y = image.shape[0] // 2

    min_distance = float('inf')
    middle_player = None

    for player in players:
        player_center_x = (player.left + player.right) // 2
        player_center_y = (player.lower + player.upper) // 2
        distance = math.sqrt((center_x - player_center_x)**2 + (center_y - player_center_y)**2)

