def answer_gray_suit_white_hat(image):
    image_patch = ImagePatch(image)
    suit_patches = image_patch.find("suit")
    hat_patches = image_patch.find("hat")

    if not suit_patches or not hat_patches:
        return "No gray suit or white hat found."

    gray_suits = [sp for sp in suit_patches if sp.verify_property("suit", "gray")]
    white_hats = [hp for hp in hat_patches if hp.verify_property("hat", "white")]

    if not gray_suits or not white_hats:
        return "No gray suit or white hat found."

    gray_suit = gray_suits[0]
    white_hat = white_hats[0]

    if gray_suit.overlaps_with(*white_hat.get_coordinates()):
        return "The gray suit and white hat are overlapping."

    distance_between = distance(gray_suit, white_hat)

    if distance_between < 0:
        return f"The gray suit and white hat are overlapping with a distance of {-distance_between:.2f}."
    else:
        return f"The gray suit and white hat are {distance_between:.2f} units apart."

