def distance(patch_a: ImagePatch, patch_b: ImagePatch) -> float:
    left_diff = abs(patch_a.left - patch_b.left)
    lower_diff = abs(patch_a.lower - patch_b.lower)
    right_diff = abs(patch_a.right - patch_b.right)
    upper_diff = abs(patch_a.upper - patch_b.upper)
    return max(left_diff, lower_diff, right_diff, upper_diff)

