def find_closest_head_with_straight_brown_hair(image):
    image_patch = ImagePatch(image)
    heads = image_patch.find("head")
    closest_head = None
    min_distance = float('inf')

    for head in heads:
        properties = head.verify_property("head", ["straight", "brown"])
        if all(properties):
            for other_head in heads:
                if head != other_head:
                    dist = distance(head, other_head)
                    if dist < min_distance:
                        min_distance = dist
                        closest_head = head

    if closest_head:
        return closest_head.llm_query("Describe the closest head with straight brown hair.")
    else:
        return "No head with straight brown hair found."

